        window.ALL_ITEMS = [...MATERIALS, ...CATALYSTS.filter(c => c.id !== 'none'), ...POTION_BASE, ...AGENTS];
        window.findItem = (id) => ALL_ITEMS.find(m => m.id === id) || null;

        window.findBestIngredients = (recipe, agentQualityBonus = 0, lager = {}, disabledIds = new Set(), ignoreEmpty = false, agent = null) => {
            const recipeEl = recipe.element.toLowerCase();
            const lagerFilled = Object.keys(lager).length > 0;
            const agFire = agent?.fire ?? 0, agEarth = agent?.earth ?? 0, agAir = agent?.air ?? 0, agWater = agent?.water ?? 0;
            const agQuality = agent?.quality ?? agentQualityBonus;

            const typeLists = recipe.ingredients.map((requiredType, slotIdx) => {
                const all = MATERIALS.filter(m => m.type === requiredType && !disabledIds.has(m.id));
                const filtered = all.filter(m => !(ignoreEmpty && lagerFilled && !(lager[m.id] > 0)));
                if (ignoreEmpty && lagerFilled && filtered.length < all.length) {
                    console.log(`[findBestIngredients] "${recipe.product}" slot ${slotIdx} (${requiredType}): ${all.length} items total, ${filtered.length} after ignoreEmpty filter. Removed:`, all.filter(m => !(lager[m.id] > 0)).map(m => `${m.name}(${lager[m.id] ?? 0})`).join(', '));
                }
                const list = filtered.sort((a, b) => {
                    const aMax = Math.max(a.fire, a.earth, a.air, a.water);
                    const bMax = Math.max(b.fire, b.earth, b.air, b.water);
                    const aMatch = aMax > 0 && a[recipeEl] === aMax ? 1 : 0;
                    const bMatch = bMax > 0 && b[recipeEl] === bMax ? 1 : 0;
                    if (bMatch !== aMatch) return bMatch - aMatch;
                    return a.quality - b.quality;
                });
                return list;
            });

            if (typeLists.some((list, i) => {
                if (list.length === 0) {
                    console.warn(`[findBestIngredients] "${recipe.product}" slot ${i} (${recipe.ingredients[i]}): NO items available after filtering!`);
                    return true;
                }
                return false;
            })) return null;

            let bestCombo = null;
            let bestScore = Infinity;

            const search = (depth, currentCombo) => {
                if (depth === 4) {
                    let f = 0, e = 0, a = 0, w = 0;
                    let qualitySum = 0;

                    for (let i = 0; i < 4; i++) {
                        let item = currentCombo[i];
                        let weight = i === 0 ? 2 : 1;
                        f += item.fire * weight; e += item.earth * weight; a += item.air * weight; w += item.water * weight;
                        qualitySum += item.quality * weight;
                    }

                    let calculatedQuality = Math.floor(qualitySum / 5) + agQuality;

                    let f2 = f + agFire, e2 = e + agEarth, a2 = a + agAir, w2 = w + agWater;
                    let dom = 'None';
                    const maxVal = Math.max(f2, e2, a2, w2);
                    if (maxVal > 0) {
                        let domCount = 0;
                        if (f2 === maxVal) { domCount++; dom = 'Fire'; }
                        if (e2 === maxVal) { domCount++; dom = 'Earth'; }
                        if (a2 === maxVal) { domCount++; dom = 'Air'; }
                        if (w2 === maxVal) { domCount++; dom = 'Water'; }
                        if (domCount > 1) dom = 'Tie';
                    }

                    const elTotal = recipeEl === 'fire' ? f2 : recipeEl === 'earth' ? e2 : recipeEl === 'air' ? a2 : w2;
                    const meetsMinScore = !(recipe.minScore > 0) || elTotal >= recipe.minScore;
                    if (dom === recipe.element && calculatedQuality >= recipe.minQuality && meetsMinScore) {
                        const qs = currentCombo.map(m => m.quality);
                        const othersAvg = (qs[1] + qs[2] + qs[3]) / 3;
                        const targetMain = othersAvg * 1.1;
                        const variance =
                            Math.pow(qs[0] - targetMain, 2) +
                            Math.pow(qs[1] - othersAvg, 2) +
                            Math.pow(qs[2] - othersAvg, 2) +
                            Math.pow(qs[3] - othersAvg, 2);
                        // Lager-Bonus: Zutaten mit mehr Bestand bevorzugen (hï¿½here Menge = niedrigerer Penalty)
                        const lagerPenalty = currentCombo.reduce((sum, m) => {
                            const amt = lager[m.id] || 0;
                            return sum + Math.max(0, 1000 - amt);
                        }, 0);
                        // Element-Malus: Zutaten bestrafen, deren primäres Element NICHT dem Rezept-Element entspricht
                        const nonMatchPenalty = currentCombo.reduce((sum, m) => {
                            const mMax = Math.max(m.fire, m.earth, m.air, m.water);
                            const primaryMatches = mMax > 0 && m[recipeEl] === mMax;
                            return sum + (primaryMatches ? 0 : 1);
                        }, 0) * 1e15;
                        // Primär: Element-Übereinstimmung; sekundär: qualitySum; tertiär: variance; quartär: lagerPenalty
                        const score = nonMatchPenalty + qualitySum * 100000000 + Math.round(variance) * 10000 + lagerPenalty;
                        if (score < bestScore) {
                            bestScore = score;
                            bestCombo = [...currentCombo];
                        }
                    }
                    return;
                }

                for (let item of typeLists[depth]) {
                    currentCombo.push(item);
                    search(depth + 1, currentCombo);
                    currentCombo.pop();
                }
            };

            search(0, []);
            if (!bestCombo) {
                // Debug: max erreichbarer elTotal und quality ohne Score-Bedingung
                let maxEl = 0, maxQ = 0;
                const best0 = typeLists[0].reduce((b, m) => m.air > (b?.air ?? -1) ? m : b, null);
                const bestQ = typeLists.map(l => l.reduce((b, m) => m.quality > (b?.quality ?? -1) ? m : b, null));
                const elVals = [best0, ...typeLists.slice(1).map(l => l.reduce((b, m) => m[recipeEl] > (b?.[recipeEl] ?? -1) ? m : b, null))];
                if (elVals.every(Boolean)) {
                    let f = 0, e = 0, a = 0, w = 0, qsum = 0;
                    elVals.forEach((m, i) => { const w2 = i === 0 ? 2 : 1; f += m.fire * w2; e += m.earth * w2; a += m.air * w2; w += m.water * w2; qsum += m.quality * w2; });
                    const elT = recipeEl === 'fire' ? f : recipeEl === 'earth' ? e : recipeEl === 'air' ? a : w;
                    const q = Math.floor(qsum / 5) + agentQualityBonus;
                    const maxVal = Math.max(f, e, a, w);
                    const domEl = [['fire', f], ['earth', e], ['air', a], ['water', w]].filter(([, v]) => v === maxVal).map(([n]) => n).join('/');
                    console.warn(`[findBestIngredients] "${recipe.product}" returned null. Best-case (max-el combo): elTotal=${elT} (need ${recipe.minScore}), quality=${q} (need ${recipe.minQuality}), dom=${domEl} (need ${recipe.element}), ignoreEmpty=${ignoreEmpty}`);
                    console.log(`  Best-case items:`, elVals.map((m, i) => `slot${i}=${m.name}(${recipeEl}:${m[recipeEl]},q:${m.quality},lager:${lager[m.id] ?? 0})`).join(', '));
                }
            }
            return bestCombo;
        };

        // Fallback-Kette: (1) ignoreEmpty + kein Agent, (2) ignoreEmpty + Agent,
        // (3) !ignoreEmpty + kein Agent, (4) !ignoreEmpty + Agent
        // Gibt { combo, agent } zurück — agent ist null wenn kein Auto-Agent gebraucht wurde
        window.findBestIngredientsWithFallback = (recipe, lager, disabledIds, ignoreEmpty) => {
            const bestAgent = window.AGENTS.find(a => a.element === recipe.element && a.quality === 20) || null;
            let combo, usedAgent = null;

            combo = window.findBestIngredients(recipe, 0, lager, disabledIds, ignoreEmpty);
            if (combo) return { combo, agent: null };

            if (bestAgent) {
                combo = window.findBestIngredients(recipe, 0, lager, disabledIds, ignoreEmpty, bestAgent);
                if (combo) return { combo, agent: bestAgent };
            }

            if (ignoreEmpty) {
                combo = window.findBestIngredients(recipe, 0, lager, disabledIds, false);
                if (combo) return { combo, agent: null };

                if (bestAgent) {
                    combo = window.findBestIngredients(recipe, 0, lager, disabledIds, false, bestAgent);
                    if (combo) return { combo, agent: bestAgent };
                }
            }

            return { combo: null, agent: null };
        };

        window.TYPE_ICONS = {
            Alloy: 1010,
            Food: 517,
            Sand: 7043,
            Wood: 1019,
            Beast: 919,
            Magic: 7117,
        };

        window.readCustomRecipes = () => {
            try { return JSON.parse(localStorage.getItem('alchemyCustomRecipes') || '[]'); }
            catch { return []; }
        };

        window.writeCustomRecipes = (recipes) => {
            localStorage.setItem('alchemyCustomRecipes', JSON.stringify(recipes));
        };

        window.readFavorites = () => {
            try { return new Set(JSON.parse(localStorage.getItem('alchemyFavorites') || '[]')); }
            catch { return new Set(); }
        };

        window.writeFavorites = (set) => {
            localStorage.setItem('alchemyFavorites', JSON.stringify([...set]));
        };

        window.readCart = () => {
            try { return JSON.parse(localStorage.getItem('alchemyCart') || '[]'); }
            catch { return []; }
        };

        window.writeCart = (cart) => {
            try { localStorage.setItem('alchemyCart', JSON.stringify(cart)); } catch { }
        };

        window.readStateCookie = () => {
            try {
                const match = document.cookie.match(/(?:^|; )alchemyState=([^;]*)/);
                return match ? JSON.parse(decodeURIComponent(match[1])) : null;
            } catch { return null; }
        };

        window.writeStateCookie = (data) => {
            document.cookie = 'alchemyState=' + encodeURIComponent(JSON.stringify(data)) + '; path=/; max-age=31536000';
        };
